"use client";
import Link from "next/link";
import { ArrowLeft, Bot, ExternalLink, Send, Sparkles } from "lucide-react";
import { useState } from "react";

const API = process.env.NEXT_PUBLIC_API_URL || "http://127.0.0.1:8000";

type Source = { state?: string; district?: string; category?: string; gi_status?: string; distance?: number; craft_name?: string };
export default function AIAssistant(){
  const [question,setQuestion]=useState("Tell me about traditional handicrafts from Uttar Pradesh");
  const [answer,setAnswer]=useState(""); const [sources,setSources]=useState<Source[]>([]); const [loading,setLoading]=useState(false); const [error,setError]=useState("");
  async function ask(){if(!question.trim())return;setLoading(true);setError("");try{const r=await fetch(`${API}/api/rag/ask`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question,top_k:5})});if(!r.ok)throw new Error(`API returned ${r.status}`);const d=await r.json();const payload=d.data??d;setAnswer(payload.answer??"");setSources(payload.sources??[]);}catch(e){setError("Could not reach the RAG service. Make sure FastAPI is running on port 8000.");}finally{setLoading(false)}}
  return <div className="page-shell"><div className="container tool-wrap"><Link href="/" className="card-link"><ArrowLeft size={15}/> Back home</Link><div className="tool-header"><div><div className="section-kicker">HASTKATHA AI</div><h1 className="section-title">Ask the craft archive.</h1><p className="section-desc">Semantic retrieval finds relevant ODOP records first. The language model then answers from that evidence.</p></div><div className="ai-icon"><Bot size={25}/></div></div>
  <div className="tool-card"><div className="field full"><label>Your question</label><textarea rows={5} value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask about a craft, state, material or GI status..."/></div><button className="btn btn-primary" style={{marginTop:16}} onClick={ask} disabled={loading}>{loading?<><span className="spinner"/> Searching knowledge...</>:<><Send size={16}/> Ask HASTKATHA</>}</button>{error&&<p style={{color:"#a9523c",marginTop:16}}>{error}</p>}{answer&&<div className="result"><div className="eyebrow"><Sparkles size={14}/> Grounded answer</div><div className="answer" style={{marginTop:15}}>{answer}</div>{sources.length>0&&<div className="sources"><div className="section-kicker">Retrieved sources</div>{sources.map((s,i)=><div className="source" key={i}><strong>{s.craft_name??"Craft record"}</strong><small>{[s.district,s.state].filter(Boolean).join(", ")} · {s.category??"handicraft"} · GI: {s.gi_status??"—"}</small></div>)}</div>}</div>}</div></div></div>
}
